const TOOL_NAME = 'catalog_search';
const DEFAULT_LIMIT = 2;
const MIN_LIMIT = 1;
const MAX_LIMIT = 5;
const ALLOWED_KEYS = new Set(['query', 'offset', 'limit']);

function asObject(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('arguments must be an object');
  }
  return args;
}

function validateString(value, name) {
  if (typeof value !== 'string') throw new Error(`${name} must be a string`);
  return value;
}

function validateNonNegativeInt(value, name, defaultValue) {
  if (value === undefined) return defaultValue;
  if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
    throw new Error(`${name} must be a non-negative integer`);
  }
  return value;
}

function validateBoundedInt(value, name, defaultValue, min, max) {
  if (value === undefined) return defaultValue;
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    throw new Error(`${name} must be an integer between ${min} and ${max}`);
  }
  return value;
}

export async function listTools() {
  return [{
    name: TOOL_NAME,
    description: 'Search catalog items by name with pagination',
    inputSchema: {
      type: 'object',
      properties: {
        query: {type: 'string', description: 'Case-insensitive substring to match against item names'},
        offset: {type: 'integer', minimum: 0, default: 0, description: 'Number of matching rows to skip'},
        limit: {type: 'integer', minimum: MIN_LIMIT, maximum: MAX_LIMIT, default: DEFAULT_LIMIT, description: 'Maximum rows to return (1-5)'}
      },
      required: ['query'],
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) throw new Error(`Unknown tool: ${name}`);
  const obj = asObject(args);

  for (const key of Object.keys(obj)) {
    if (!ALLOWED_KEYS.has(key)) throw new Error(`Unexpected argument: ${key}`);
  }

  const query = validateString(obj.query, 'query');
  const offset = validateNonNegativeInt(obj.offset, 'offset', 0);
  const limit = validateBoundedInt(obj.limit, 'limit', DEFAULT_LIMIT, MIN_LIMIT, MAX_LIMIT);

  const needle = query.toLowerCase();
  const matches = items.filter((it) => it.name.toLowerCase().includes(needle));
  const page = matches.slice(offset, offset + limit);
  const nextOffset = offset + page.length < matches.length ? offset + page.length : null;

  const payload = {items: page, next_offset: nextOffset};
  return {content: [{type: 'text', text: JSON.stringify(payload)}]};
}

