import('./server.mjs').then(async ({callTool, listTools}) => {
  const tools = await listTools();
  console.log('tool name:', tools[0].name);
  console.log('required:', JSON.stringify(tools[0].inputSchema.required));
  console.log('limit max:', tools[0].inputSchema.properties.limit.maximum);

  const cases = [
    ['case-insensitive', {query:'WIDGET', limit:2}],
    ['paginate page 2', {query:'widget', offset:2, limit:2}],
    ['no matches', {query:'nope'}],
    ['empty result after offset', {query:'widget', offset:10}],
    ['exact end', {query:'widget', offset:3, limit:2}],
  ];
  for (const [label, args] of cases) {
    try { console.log(label, '->', JSON.stringify(await callTool('catalog_search', args))); }
    catch (e) { console.log(label, 'ERR:', e.message); }
  }

  const rejections = [
    ['unknown tool', () => callTool('nope', {query:'x'})],
    ['missing query', () => callTool('catalog_search', {})],
    ['non-string query', () => callTool('catalog_search', {query:1})],
    ['limit too high', () => callTool('catalog_search', {query:'x', limit:6})],
    ['limit too low', () => callTool('catalog_search', {query:'x', limit:0})],
    ['limit decimal', () => callTool('catalog_search', {query:'x', limit:2.5})],
    ['limit string', () => callTool('catalog_search', {query:'x', limit:'2'})],
    ['offset negative', () => callTool('catalog_search', {query:'x', offset:-1})],
    ['offset decimal', () => callTool('catalog_search', {query:'x', offset:1.5})],
    ['extra arg', () => callTool('catalog_search', {query:'x', foo:1})],
    ['args not object', () => callTool('catalog_search', 'oops')],
    ['args null', () => callTool('catalog_search', null)],
  ];
  for (const [label, fn] of rejections) {
    try { console.log(label, '-> UNEXPECTED PASS:', JSON.stringify(await fn())); }
    catch (e) { console.log(label, '-> rejected:', e.message); }
  }
});
""}

